from collections import Counter

def transform(grid):
    """Fill the single background cell between horizontally spaced motif cells."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(1, w - 1):
            v = grid[r][c - 1]
            if v != bg and grid[r][c] == bg and grid[r][c + 1] == v:
                out[r][c] = 2
    return out

